Merge sort fits a linked list well because splitting and merging can both be done with pointers. The slow pointer reaches the middle, then the two sorted halves are joined by comparing their front nodes.

The list links are changed, but no node values are copied.

```cpp
/*
Definition of singly linked list:
struct ListNode
{
    int val;
    ListNode *next;
    ListNode()
    {
        val = 0;
        next = NULL;
    }
    ListNode(int data1)
    {
        val = data1;
        next = NULL;
    }
    ListNode(int data1, ListNode *next1)
    {
        val = data1;
        next = next1;
    }
};
*/

class Solution {
    ListNode* mergeLists(ListNode* first, ListNode* second) {
        ListNode dummy(0);
        ListNode* tail = &dummy;

        while (first != NULL && second != NULL) {
            if (first->val <= second->val) {
                tail->next = first;
                first = first->next;
            } else {
                tail->next = second;
                second = second->next;
            }
            tail = tail->next;
        }

        if (first != NULL) {
            tail->next = first;
        } else {
            tail->next = second;
        }

        return dummy.next;
    }

public:
    ListNode* sortList(ListNode* head) {
        if (head == NULL || head->next == NULL) {
            return head;
        }

        ListNode* slow = head;
        ListNode* fast = head->next;

        while (fast != NULL && fast->next != NULL) {
            slow = slow->next;
            fast = fast->next->next;
        }

        ListNode* secondHalf = slow->next;
        slow->next = NULL;

        ListNode* left = sortList(head);
        ListNode* right = sortList(secondHalf);

        return mergeLists(left, right);
    }
};
```

Time complexity: O(n log n)

Space complexity: O(log n) for the recursion stack.

This is a non-recursive merge sort. It first merges pairs of one-node lists, then pairs of two-node lists, and keeps doubling the block size. The list is split and joined by changing `next` pointers.

The dry run for `5 -> 2 -> 4 -> 1` starts with blocks of size 1. It merges `5,2` into `2,5` and `4,1` into `1,4`. With block size 2, those results merge into `1,2,4,5`.

```cpp
/*
Definition of singly linked list:
struct ListNode
{
    int val;
    ListNode *next;
    ListNode()
    {
        val = 0;
        next = NULL;
    }
    ListNode(int data1)
    {
        val = data1;
        next = NULL;
    }
    ListNode(int data1, ListNode *next1)
    {
        val = data1;
        next = next1;
    }
};
*/

class Solution {
    ListNode* mergeParts(ListNode* left, ListNode* right) {
        ListNode dummy(0);
        ListNode* tail = &dummy;

        while (left != NULL && right != NULL) {
            if (left->val <= right->val) {
                tail->next = left;
                left = left->next;
            } else {
                tail->next = right;
                right = right->next;
            }
            tail = tail->next;
        }

        tail->next = left != NULL ? left : right;
        return dummy.next;
    }

public:
    ListNode* sortList(ListNode* head) {
        if (head == NULL || head->next == NULL) {
            return head;
        }

        int length = 0;
        for (ListNode* node = head; node != NULL; node = node->next) {
            length++;
        }

        ListNode dummy(0, head);

        for (int width = 1; width < length; width *= 2) {
            ListNode* current = dummy.next;
            ListNode* mergedTail = &dummy;

            while (current != NULL) {
                ListNode* left = current;
                ListNode* right = left;

                for (int i = 1; i < width && right->next != NULL; i++) {
                    right = right->next;
                }

                if (right == NULL) {
                    break;
                }

                ListNode* nextPart = right->next;
                right->next = NULL;

                right = nextPart;
                ListNode* scan = right;
                for (int i = 1; i < width && scan != NULL && scan->next != NULL; i++) {
                    scan = scan->next;
                }

                if (scan != NULL) {
                    nextPart = scan->next;
                    scan->next = NULL;
                } else {
                    nextPart = NULL;
                }

                mergedTail->next = mergeParts(left, right);
                while (mergedTail->next != NULL) {
                    mergedTail = mergedTail->next;
                }

                current = nextPart;
            }
        }

        return dummy.next;
    }
};
```

Time complexity: O(n log n), with no recursive calls.

Space complexity: O(1) extra space. The input list is rearranged in place.

The list is divided until each part has one node. A one-node list is already sorted, so the merge step only needs to pick the smaller node from the two halves.

Dry run for `4 -> 1 -> 3`: split into `4` and `1 -> 3`, then into `1` and `3`. Merging gives `1 -> 3`, and the final merge gives `1 -> 3 -> 4`.

```java
/*Definition of singly linked list:
class ListNode {
    int val;
    ListNode next;

    ListNode() {
        val = 0;
        next = null;
    }

    ListNode(int data1) {
        val = data1;
        next = null;
    }

    ListNode(int data1, ListNode next1) {
        val = data1;
        next = next1;
    }
}
 */

class Solution {
    private ListNode merge(ListNode left, ListNode right) {
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;

        while (left != null && right != null) {
            if (left.val <= right.val) {
                tail.next = left;
                left = left.next;
            } else {
                tail.next = right;
                right = right.next;
            }
            tail = tail.next;
        }

        tail.next = left != null ? left : right;
        return dummy.next;
    }

    public ListNode sortList(ListNode head) {
        if (head == null || head.next == null) {
            return head;
        }

        ListNode slow = head;
        ListNode fast = head.next;

        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        ListNode rightStart = slow.next;
        slow.next = null;

        ListNode left = sortList(head);
        ListNode right = sortList(rightStart);

        return merge(left, right);
    }
}
```

Time complexity: O(n log n), since every level processes all nodes once.

Space complexity: O(log n) for recursive calls. The nodes themselves are reused.

Insertion sort works nicely for a list that is already almost sorted. The `sortedHead` list stores the processed part. Each remaining node is inserted into the right place by changing links.

For example, with `2 -> 1 -> 3`, node `2` starts the sorted part. Node `1` goes before it, and node `3` goes after it.

```csharp
/*Definition for singly-linked list.
public class ListNode {
    public int val;
    public ListNode next;
    public ListNode(int val=0, ListNode next=null) {
        this.val = val;
        this.next = next;
    }
}
*/
public class Solution {
    public ListNode sortList(ListNode head) {
        ListNode sortedHead = null;
        ListNode current = head;

        while (current != null) {
            ListNode nextNode = current.next;

            if (sortedHead == null || current.val < sortedHead.val) {
                current.next = sortedHead;
                sortedHead = current;
            } else {
                ListNode position = sortedHead;

                while (position.next != null && position.next.val <= current.val) {
                    position = position.next;
                }

                current.next = position.next;
                position.next = current;
            }

            current = nextNode;
        }

        return sortedHead;
    }
}
```

Time complexity: O(n squared) in the worst case, such as a reverse-sorted list.

Space complexity: O(1) extra space. The original nodes are moved, so the input links are changed.

## Solution
```java
/*Definition of singly linked list:
class ListNode {
    int val;
    ListNode next;

    ListNode() {
        val = 0;
        next = null;
    }

    ListNode(int data1) {
        val = data1;
        next = null;
    }

    ListNode(int data1, ListNode next1) {
        val = data1;
        next = next1;
    }
}
 */

class Solution {
    public ListNode sortList(ListNode head) {
        if(head==null) return null;
        return mergesort(head);
    }

    public ListNode mergesort(ListNode head) {
        if(head.next == null) return head;
        ListNode slow=head;
        ListNode fast=head.next;
        while(fast != null && fast.next != null){
            slow=slow.next;
            fast=fast.next.next;
        }
        ListNode right = mergesort(slow.next);
        slow.next=null;
        ListNode left = mergesort(head);
        return merge(left, right);
    }

    public ListNode merge(ListNode left, ListNode right){
        ListNode head = new ListNode();
        ListNode temp = head;
        while(left != null && right != null){
            if(left.val < right.val){
                temp.next = left;
                left=left.next;               
            }else{
                temp.next = right;
                right = right.next;
            }
            temp=temp.next;
        }
        while(left != null){
            temp.next = left;
            left = left.next;
            temp = temp.next;   
        } 
        while(right != null){
            temp.next = right;
            right = right.next;
            temp = temp.next;   
        }
        return head.next;
    }
}
```

